        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = function(k){ return window.mySimulation.t(k); };
            var last = history[history.length - 1];
            var overall = last.results ? last.results.overallScore || 0 : 0;
            var performanceId = 'needs_improvement', gradeKey = 'grade_needs';
            if (overall >= 70) { performanceId = 'excellent'; gradeKey = 'grade_excellent'; }
            else if (overall >= 55) { performanceId = 'good'; gradeKey = 'grade_good'; }
            else if (overall >= 40) { performanceId = 'satisfactory'; gradeKey = 'grade_satisfactory'; }

            var insights = [];
            if (last.results) {
                if (last.results.financialScore < 50) insights.push(t('insight_fin_low'));
                if (last.results.learningScore < 40) insights.push(t('insight_talent_low'));
                if (last.results.orgScore < 50) insights.push(t('insight_org_low'));
                if (last.results.marketScore > 60) insights.push(t('insight_market_high'));
                if (overall >= 65) insights.push(t('insight_balanced'));
            }

            return {
                overallScore: overall,
                score: overall,
                performanceId: performanceId,
                performance: t(gradeKey),
                beatTarget: overall >= 55,
                insights: insights,
                financialScore: last.results ? (last.results.financialScore || 0) : 0,
                marketScore: last.results ? (last.results.marketScore || 0) : 0,
                orgScore: last.results ? (last.results.orgScore || 0) : 0,
                learningScore: last.results ? (last.results.learningScore || 0) : 0
            };
        }

        formatCompletionMessage(summary) {
            var t = function(k){ return window.mySimulation.t(k); };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var grade = s.performance || '';
            var beat = !!s.beatTarget;
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var badgeClass = beat ? 'org-cm-badge-pass' : 'org-cm-badge-miss';
            var badgeText = beat ? t('cm_badge_beat') : t('cm_badge_missed');
            var kpi = function(label, val){ return '<div class="org-cm-kpi"><div class="org-cm-kpi-val">' + val + '</div><div class="org-cm-kpi-label">' + label + '</div></div>'; };
            var insightHtml = '';
            insights.forEach(function(it){ insightHtml += '<li>' + it + '</li>'; });
            return '' +
              '<div class="org-cm">' +
                '<div class="org-cm-scoreblock">' +
                  '<div class="org-cm-scorenum">' + score + '<span class="org-cm-scoremax">/100</span></div>' +
